// FactBank.swift
// My built-in general-knowledge and cybersecurity question bank.
// Ported from my web prototype's bank, plus the answers James confirmed
// on his own quiz screens (Pokémon, "Honest Abe", residual risk).
// Matching is by keyword: every keyword must appear in the question,
// and the answer is then matched against the printed choices by TEXT,
// never by letter — the choices can shuffle.
//
// The cybersecurity bank is study knowledge for this prototype only.
// It is NOT a claim that I hold CISSP — I hold CompTIA Security+.

import Foundation

/// One banked fact: keywords that must all appear in the question,
/// the correct answer text as printed, and a one-line reason.
public struct Fact: Sendable {
    public let keywords: [String]
    public let answer: String
    public let reason: String
    public init(keywords: [String], answer: String, reason: String) {
        self.keywords = keywords
        self.answer = answer
        self.reason = reason
    }
}

/// One cybersecurity term and its plain-English definition, used when a
/// question names a term and the options are definitions of it.
public struct CyberDefinition: Sendable {
    public let term: String
    public let definition: String
    public init(term: String, definition: String) {
        self.term = term
        self.definition = definition
    }
}

