    Fact(keywords: ["stop an incident from spreading"], answer: "Containment", reason: "Limiting the damage and spread of an incident is containment."),
    Fact(keywords: ["remove the root cause", "malware from all systems"], answer: "Eradication", reason: "Eradication removes the root cause of the incident, such as malware and compromised accounts."),
    Fact(keywords: ["restore systems", "back to normal operations"], answer: "Recovery", reason: "Recovery restores systems to normal operation and monitors them for recurrence."),
    Fact(keywords: ["final phase", "incident response", "what went well"], answer: "Lessons learned", reason: "Lessons learned — reviewing what happened and improving — is the final phase of incident response."),
    Fact(keywords: ["lessons learned", "incident response"], answer: "Lessons learned", reason: "The post-incident review is the lessons learned phase."),
    Fact(keywords: ["ale", "calculated"], answer: "SLE x ARO", reason: "CISSP D1 — ALE (Annualized Loss Expectancy) = SLE × ARO."),
    Fact(keywords: ["annualized loss expectancy", "formula"], answer: "SLE x ARO", reason: "CISSP D1 — ALE = Single Loss Expectancy × Annualized Rate of Occurrence."),
    Fact(keywords: ["single loss expectancy", "formula"], answer: "AV x EF", reason: "CISSP D1 — SLE = Asset Value (AV) × Exposure Factor (EF)."),
    Fact(keywords: ["sle", "asset value"], answer: "AV x EF", reason: "CISSP D1 — SLE = AV × EF."),
    Fact(keywords: ["assigns a dollar value", "risk analysis"], answer: "Quantitative", reason: "CISSP D1 — Quantitative risk analysis assigns monetary (dollar) values; qualitative uses subjective ratings."),
    Fact(keywords: ["subjective", "high medium low", "risk"], answer: "Qualitative", reason: "CISSP D1 — Qualitative analysis rates risk subjectively (high / medium / low) instead of in dollars."),
    Fact(keywords: ["buying insurance", "risk"], answer: "Risk transference", reason: "CISSP D1 — Buying insurance transfers (shares) the financial impact of a risk with a third party."),
    Fact(keywords: ["transferring risk", "third party"], answer: "Risk transference", reason: "CISSP D1 — Risk transference shifts the impact to a third party, e.g. through insurance."),
    Fact(keywords: ["cost of mitigation exceeds", "accept"], answer: "Risk acceptance", reason: "CISSP D1 — When mitigation costs more than the risk is worth, management formally accepts the risk."),
    Fact(keywords: ["keep business operating", "during a disruption"], answer: "Business continuity", reason: "CISSP D1 — A Business Continuity Plan keeps critical business functions running during a disruption."),
    Fact(keywords: ["business continuity plan", "stands for bcp"], answer: "Business Continuity Plan", reason: "CISSP D1 — BCP is the Business Continuity Plan."),
    Fact(keywords: ["restore it systems", "after a disaster"], answer: "Disaster Recovery Plan", reason: "CISSP D1 — A Disaster Recovery Plan focuses on restoring IT systems after a disaster; the BCP covers the whole business."),
    Fact(keywords: ["disaster recovery", "it systems"], answer: "Disaster Recovery Plan", reason: "CISSP D1 — Disaster recovery is the IT-focused part of recovery, under the broader BCP."),
    Fact(keywords: ["research", "before acting", "investigate"], answer: "Due diligence", reason: "CISSP D1 — Due diligence is investigating and understanding risks before acting."),
    Fact(keywords: ["prudent actions", "implementing controls", "protect assets"], answer: "Due care", reason: "CISSP D1 — Due care is taking the prudent actions a reasonable person would to protect assets."),
    Fact(keywords: ["maximum tolerable downtime"], answer: "MTD", reason: "CISSP D1 — MTD is the Maximum Tolerable Downtime before a business suffers unacceptable harm."),
    Fact(keywords: ["recovery time objective"], answer: "RTO", reason: "CISSP D1 — RTO is the target time to restore a system after a disruption."),
    Fact(keywords: ["recovery point objective"], answer: "RPO", reason: "CISSP D1 — RPO is the maximum amount of data loss measured in time (how far back you must restore from)."),
    Fact(keywords: ["maximum data loss", "acceptable", "time"], answer: "RPO", reason: "CISSP D1 — The acceptable data-loss window is the Recovery Point Objective (RPO)."),
    Fact(keywords: ["accountable for classifying data"], answer: "Data owner", reason: "CISSP D2 — The data owner decides classification and is accountable for the data."),
    Fact(keywords: ["data owner", "responsible for"], answer: "Data owner", reason: "CISSP D2 — The data owner is accountable for data classification and protection requirements."),
    Fact(keywords: ["implements the controls", "day to day", "data"], answer: "Data custodian", reason: "CISSP D2 — The data custodian handles day-to-day storage, protection, and backup as directed by the owner."),
    Fact(keywords: ["day to day", "data owner"], answer: "Data custodian", reason: "CISSP D2 — Day-to-day protection of data, carried out as directed by the data owner, is the data custodian's job."),
    Fact(keywords: ["day to day protection of data"], answer: "Data custodian", reason: "CISSP D2 — Day-to-day storage, protection, and backup of data is the data custodian role."),
    Fact(keywords: ["day to day storage"], answer: "Data custodian", reason: "CISSP D2 — Day-to-day storage and backup of data is handled by the data custodian."),
    Fact(keywords: ["data custodian"], answer: "Data custodian", reason: "CISSP D2 — Custodians implement the owner's requirements: storage, backups, and access enforcement."),
