    Fact(keywords: ["bell lapadula", "no read up"], answer: "Bell-LaPadula", reason: "CISSP D3 — Bell-LaPadula protects confidentiality: no read up, no write down."),
    Fact(keywords: ["no read up", "no write down"], answer: "Bell-LaPadula", reason: "CISSP D3 — 'No read up, no write down' is the Bell-LaPadula confidentiality model."),
    Fact(keywords: ["bell lapadula"], answer: "Bell-LaPadula", reason: "CISSP D3 — Bell-LaPadula is the confidentiality model (no read up, no write down)."),
