    Fact(keywords: ["hardware security module"], answer: "HSM", reason: "CISSP D3 — HSM stands for Hardware Security Module."),
    Fact(keywords: ["verifies firmware", "boot process", "trusted"], answer: "Secure Boot", reason: "CISSP D3 — Secure Boot verifies that firmware and bootloaders are signed and trusted before loading them."),
    Fact(keywords: ["osi model", "how many layers"], answer: "7", reason: "CISSP D4 — The OSI model has 7 layers, from Physical (1) to Application (7)."),
