    Fact(keywords: ["divides a network", "smaller isolated segments"], answer: "Network segmentation", reason: "CISSP D4 — Segmentation isolates systems into smaller zones, limiting how far an attacker can move."),
    Fact(keywords: ["verifying a user", "identity", "password"], answer: "Authentication", reason: "CISSP D5 — Authentication verifies a claimed identity (e.g. password, MFA); authorization decides what they may do."),
    Fact(keywords: ["proves their identity"], answer: "Authentication", reason: "CISSP D5 — Proving who you are is authentication."),
