    Fact(keywords: ["single sign on"], answer: "Single Sign-On", reason: "CISSP D5 — SSO stands for Single Sign-On."),
    Fact(keywords: ["something you know", "something you have", "something you are"], answer: "Multi-factor authentication", reason: "CISSP D5 — MFA combines factors: something you know, have, and are."),
    Fact(keywords: ["two or more", "authentication factors"], answer: "Multi-factor authentication", reason: "CISSP D5 — Using two or more different factor types is multi-factor authentication."),
    Fact(keywords: ["fingerprint scan", "factor"], answer: "Something you are", reason: "CISSP D5 — Biometrics like a fingerprint are 'something you are'."),
    Fact(keywords: ["actively exploits vulnerabilities"], answer: "Penetration test", reason: "CISSP D6 — A penetration test goes beyond scanning: it actively exploits vulnerabilities like a real attacker."),
    Fact(keywords: ["attempts to exploit", "authorized"], answer: "Penetration test", reason: "CISSP D6 — Authorized exploitation of weaknesses is a penetration test."),
    Fact(keywords: ["identifies vulnerabilities", "without exploiting"], answer: "Vulnerability scan", reason: "CISSP D6 — A vulnerability scan identifies known weaknesses but does not exploit them."),
    Fact(keywords: ["scans for known vulnerabilities"], answer: "Vulnerability scan", reason: "CISSP D6 — Scanning finds and reports vulnerabilities; a pen test proves them by exploiting."),
    Fact(keywords: ["no prior knowledge", "tester", "black box"], answer: "Black box", reason: "CISSP D6 — Black box testing gives the tester no prior knowledge of the system."),
    Fact(keywords: ["no information about the system", "testing"], answer: "Black box", reason: "CISSP D6 — Testing with zero internal knowledge is black box testing."),
    Fact(keywords: ["full knowledge", "source code", "testing"], answer: "White box", reason: "CISSP D6 — White box testing gives the tester full knowledge, including source code."),
    Fact(keywords: ["partial knowledge", "testing"], answer: "Gray box", reason: "CISSP D6 — Gray box testing gives partial knowledge — like a normal user's view plus some internals."),
    Fact(keywords: ["random invalid data", "crash the application"], answer: "Fuzzing", reason: "CISSP D6 — Fuzzing feeds random, unexpected data to an application to find crashes and flaws."),
    Fact(keywords: ["fuzzing"], answer: "Fuzzing", reason: "CISSP D6 — Fuzzing tests with malformed, random inputs to uncover bugs."),
    Fact(keywords: ["most volatile", "collect first"], answer: "Order of volatility", reason: "CISSP D7 — Evidence is collected in order of volatility: CPU cache and RAM first, disks and logs later."),
    Fact(keywords: ["order of volatility"], answer: "Order of volatility", reason: "CISSP D7 — The order of volatility runs from most volatile (memory) to least (backups/archives)."),
    Fact(keywords: ["who handled the evidence"], answer: "Chain of custody", reason: "CISSP D7 — Chain of custody documents everyone who handled evidence, so it stays admissible."),
    Fact(keywords: ["chain of custody"], answer: "Chain of custody", reason: "CISSP D7 — Chain of custody tracks evidence handling from collection to court."),
    Fact(keywords: ["automates", "orchestrates incident response"], answer: "SOAR", reason: "CISSP D7 — SOAR (Security Orchestration, Automation and Response) automates response playbooks; a SIEM only detects and alerts."),
    Fact(keywords: ["security orchestration automation and response"], answer: "SOAR", reason: "CISSP D7 — SOAR stands for Security Orchestration, Automation and Response."),
    Fact(keywords: ["monitors", "24 7", "detect and respond to threats"], answer: "Security Operations Center", reason: "CISSP D7 — A SOC (Security Operations Center) monitors and responds to threats around the clock."),
    Fact(keywords: ["security operations center"], answer: "Security Operations Center", reason: "CISSP D7 — SOC stands for Security Operations Center."),
    Fact(keywords: ["backs up only data changed since the last backup"], answer: "Incremental backup", reason: "CISSP D7 — An incremental backup copies only what changed since the last backup of any type."),
    Fact(keywords: ["since the last full backup", "changed data"], answer: "Differential backup", reason: "CISSP D7 — A differential backup copies everything changed since the last full backup."),
    Fact(keywords: ["raid 1", "mirroring"], answer: "RAID 1", reason: "CISSP D7 — RAID 1 is mirroring: identical copies on two disks."),
    Fact(keywords: ["mirroring", "two disks", "raid"], answer: "RAID 1", reason: "CISSP D7 — Mirroring across two disks is RAID 1."),
