    Fact(keywords: ["striping with parity"], answer: "RAID 5", reason: "CISSP D7 — Striping with parity is RAID 5."),
    Fact(keywords: ["malicious sql", "database query"], answer: "SQL injection", reason: "CISSP D8 — SQL injection inserts malicious SQL into an application's database query."),
    Fact(keywords: ["sql injection"], answer: "SQL injection", reason: "CISSP D8 — SQL injection exploits unsanitized input in database queries; parameterized queries prevent it."),
    Fact(keywords: ["malicious script", "victim browser", "web page"], answer: "Cross-Site Scripting", reason: "CISSP D8 — XSS injects malicious scripts into web pages viewed by other users."),
    Fact(keywords: ["cross site scripting"], answer: "Cross-Site Scripting", reason: "CISSP D8 — XSS stands for Cross-Site Scripting."),
    Fact(keywords: ["xss", "stands for"], answer: "Cross-Site Scripting", reason: "CISSP D8 — XSS stands for Cross-Site Scripting."),
    Fact(keywords: ["more data than a buffer can hold"], answer: "Buffer overflow", reason: "CISSP D8 — A buffer overflow writes more data than a buffer can hold, corrupting memory."),
    Fact(keywords: ["buffer overflow"], answer: "Buffer overflow", reason: "CISSP D8 — Buffer overflows come from missing bounds checking on input."),
