    Fact(keywords: ["tricks a logged in user", "unintended request"], answer: "Cross-Site Request Forgery", reason: "CISSP D8 — CSRF tricks an authenticated user's browser into sending an unintended request."),
    Fact(keywords: ["cross site request forgery"], answer: "Cross-Site Request Forgery", reason: "CISSP D8 — CSRF stands for Cross-Site Request Forgery."),
