    public static let cyberDefinitions: [CyberDefinition] = [
    CyberDefinition(term: "phishing", definition: "Fraudulent email or message that tricks people into revealing passwords, credentials, or sensitive information, or into installing malware."),
    CyberDefinition(term: "spear phishing", definition: "Targeted phishing aimed at a specific person or organization using personal details to appear convincing."),
    CyberDefinition(term: "ransomware", definition: "Malicious software that encrypts the victim files and demands payment in exchange for the decryption key."),
    CyberDefinition(term: "firewall", definition: "A device or software that monitors and filters network traffic, allowing or blocking it based on security rules."),
    CyberDefinition(term: "trojan", definition: "Malware disguised as legitimate software that tricks users into installing it."),
    CyberDefinition(term: "worm", definition: "Malware that replicates itself and spreads across networks automatically without a host file or user action."),
    CyberDefinition(term: "virus", definition: "Malware that attaches to a host file or program and spreads when the file is executed or shared."),
    CyberDefinition(term: "keylogger", definition: "Malware that secretly records keystrokes to steal passwords and other typed information."),
    CyberDefinition(term: "rootkit", definition: "Tools that hide malware and maintain privileged root level access on a compromised system."),
    CyberDefinition(term: "honeypot", definition: "A decoy system intentionally left exposed to attract, detect, and study attackers."),
    CyberDefinition(term: "hashing", definition: "A one way function that converts data into a fixed length fingerprint used to verify integrity and cannot be reversed."),
    CyberDefinition(term: "symmetric encryption", definition: "Encryption that uses the same single shared key to encrypt and decrypt data."),
    CyberDefinition(term: "asymmetric encryption", definition: "Encryption that uses a pair of keys, a public key for encryption and a private key for decryption."),
    CyberDefinition(term: "vpn", definition: "A virtual private network that creates an encrypted tunnel for data over a public network such as the internet."),
    CyberDefinition(term: "siem", definition: "A system that collects, correlates, and analyzes log and security event data from across the organization to detect threats."),
    CyberDefinition(term: "zero trust", definition: "A security model that trusts no user or device by default and always verifies identity before granting access."),
    CyberDefinition(term: "least privilege", definition: "The principle that users and systems should have only the minimum access needed to perform their job."),
    CyberDefinition(term: "defense in depth", definition: "Using multiple overlapping layers of security controls so that failure of one layer does not expose the whole system."),
    CyberDefinition(term: "kerberos", definition: "A ticket based authentication protocol that uses a trusted third party to verify users and services."),
    CyberDefinition(term: "sql injection", definition: "An attack that inserts malicious SQL code into an application input so it runs in the database query."),
    CyberDefinition(term: "buffer overflow", definition: "An attack or flaw where more data is written into a memory buffer than it can hold, corrupting memory and possibly executing code."),
    CyberDefinition(term: "penetration test", definition: "An authorized simulated attack that actively exploits vulnerabilities to test how far an attacker could get."),
    CyberDefinition(term: "vulnerability scan", definition: "An automated scan that identifies known vulnerabilities and missing patches without exploiting them."),
    CyberDefinition(term: "chain of custody", definition: "Documentation that records who collected, handled, and stored evidence so it remains admissible in court."),
    CyberDefinition(term: "data custodian", definition: "The person or team responsible for the day to day storage, protection, backup, and handling of data as directed by the data owner."),
    CyberDefinition(term: "data owner", definition: "The person accountable for information assets who decides data classification and who may access the data."),
    CyberDefinition(term: "bell lapadula", definition: "A confidentiality security model with no read up and no write down rules based on classification levels."),
    CyberDefinition(term: "biba", definition: "An integrity security model with no read down and no write up rules that prevents contamination of trusted data."),
    CyberDefinition(term: "fuzzing", definition: "Testing by feeding random, invalid, and unexpected data into an application to find crashes and vulnerabilities."),
    CyberDefinition(term: "man in the middle", definition: "An attack where the attacker secretly intercepts and relays communication between two parties who believe they are talking directly."),
    ]
}
